/* Still UI foundation: design tokens, light and dark themes.
   Derived from Arc Library (MIT, https://github.com/kuratlielia/arc-library) and retuned to a cool neutral, indigo-accent palette.
   Components read the semantic tokens below (never raw colors), so a theme change starts and ends in this file. */
:root {
  color-scheme: light;
  font-family: var(--font-body);
  --neutral-0: #ffffff;
  --neutral-1: #fcfdff;
  --neutral-2: #f8fafc;
  --neutral-3: #f1f5f9;
  --neutral-4: #e2e8f0;
  --neutral-5: #cbd5e1;
  --neutral-6: #94a3b8;
  --neutral-7: #64748b;
  --neutral-8: #475569;
  --neutral-9: #334155;
  --neutral-10: #1e293b;
  --neutral-11: #0f172a;
  --background: var(--neutral-2);
  --surface: var(--neutral-0);
  --surface-raised: var(--neutral-0);
  --surface-muted: var(--neutral-3);
  --foreground: var(--neutral-11);
  --text-secondary: var(--neutral-8);
  --text-muted: var(--neutral-7);
  --border: var(--neutral-4);
  --border-subtle: var(--neutral-3);
  --border-strong: var(--neutral-5);
  --accent: #4f46e5;
  --accent-strong: #4338ca;
  --accent-subtle: rgb(79 70 229 / .1);
  --accent-foreground: var(--background);
  /* Selection controls (switch, checkbox, radio, slider). --control-on fills a chosen control; --control-glyph is the check or dot drawn on it;
     thumbs stay white in both states so they always read against the track. Tuned per accent below so white thumbs hold on every hue. */
  --control-on: #4f46e5;
  --control-glyph: #ffffff;
  --control-track: var(--neutral-4);
  --control-track-hover: var(--neutral-5);
  --control-thumb: #ffffff;
  --control-thumb-on: #ffffff;
  --control-thumb-shadow: 0 0 0 .5px rgb(15 23 42 / .07), 0 1px 2px rgb(15 23 42 / .14), 0 2px 6px rgb(15 23 42 / .06);
  --control-on-subtle: color-mix(in oklab, var(--control-on) 10%, transparent);
  /* Slider fills: the accent, deepened so a white thumb keeps its edge on the track. */
  --control-fill: var(--accent-strong);
  /* Pointer focus draws no ring (product decision). Keyboard focus uses the outline at the end of this file; tune it with
     --focus-outline, --focus-outline-width and --focus-outline-offset. */
  --focus-ring: transparent;
  --success: #16a34a;
  --warning: #d97706;
  --danger: #dc2626;
  --shadow-resting: 0 1px 2px rgb(15 23 42 / .04);
  --shadow-raised: 0 6px 18px rgb(15 23 42 / .07), 0 1px 3px rgb(15 23 42 / .04);
  --shadow-floating: 0 20px 48px rgb(15 23 42 / .12), 0 3px 10px rgb(15 23 42 / .05);
  /* Brand gradient: soft indigo to violet. Light enough for dark text (--still-gradient-foreground, >12:1). */
  --still-gradient-from: #e0e7ff;
  --still-gradient-to: #ede9fe;
  --still-gradient: linear-gradient(100deg, var(--still-gradient-from), var(--still-gradient-to));
  --still-gradient-foreground: #1e1b4b;
  /* Faint wash for backgrounds and tinted panels. */
  --still-gradient-soft: linear-gradient(135deg, #f5f3ff, #eef2ff);
  /* Hairline borders and rules. */
  --still-gradient-line: linear-gradient(100deg, #c7d2fe, #ddd6fe);
  /* Text-safe stops for gradient text and small marks (>4.5:1 on the surface). */
  --still-gradient-ink: linear-gradient(100deg, #4338ca, #6d28d9);
  --space-1: .25rem; --space-2: .5rem; --space-3: .75rem; --space-4: 1rem;
  --space-5: 1.25rem; --space-6: 1.5rem; --space-8: 2rem; --space-10: 2.5rem;
  --space-12: 3rem; --space-16: 4rem; --space-20: 5rem; --space-24: 6rem;
  --radius-control: 1.125rem; --radius-panel: 1.625rem; --radius-surface: 2.125rem; --radius-pill: 9999px;
  --control-height-sm: 2.25rem; --control-height-md: 2.75rem; --control-height-lg: 3.125rem;
  --font-display: var(--font-geist, "Segoe UI"), system-ui, -apple-system, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --font-body: var(--font-inter, "Segoe UI"), system-ui, -apple-system, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --text-xs: .75rem; --text-sm: .875rem; --text-base: 1rem; --text-lg: 1.125rem;
  --text-xl: 1.375rem; --text-2xl: 1.75rem; --text-3xl: 2.25rem;
  --text-4xl: 3.25rem; --text-5xl: 4.5rem;
  --tracking-display: -.03em; --tracking-body: -.01em;
  --leading-display: 1.1; --leading-body: 1.4;
  --ease-enter: cubic-bezier(.16,1,.3,1);
  --ease-standard: cubic-bezier(.22,1,.36,1);
  --ease-exit: cubic-bezier(.7,0,.84,0);
  --ease-in-out: cubic-bezier(.65,0,.35,1);
  /* Critically damped spring: fast start, smooth settle, never overshoots (no jitter). Pair with --duration-spring for transform transitions. */
  --ease-spring: linear(0, 0.0213, 0.0739, 0.1443, 0.2235, 0.305, 0.3849, 0.4606, 0.5305, 0.594, 0.6508, 0.7011, 0.7452, 0.7836, 0.8168, 0.8454, 0.8699, 0.8907, 0.9084, 0.9234, 0.9361, 0.9467, 0.9557, 0.9632, 0.9694, 0.9747, 0.979, 0.9826, 0.9857, 0.9882, 0.9902, 0.992, 0.9934, 0.9946, 0.9955, 0.9963, 1);
  --duration-instant: 120ms; --duration-fast: 160ms; --duration-standard: 240ms; --duration-considered: 480ms; --duration-spring: 580ms;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --background: #0b1120;
  --surface: #0f172a;
  --surface-raised: #152238;
  /* Keep muted surfaces and hover states distinct from the base surface in dark mode. */
  --surface-muted: #1c2a41;
  --foreground: #e2e8f0;
  --text-secondary: #a8b6c9;
  --text-muted: #7f8ea3;
  --border: #23324b;
  --border-subtle: #1a2740;
  --border-strong: #3b4f6e;
  --focus-ring: transparent;
  --accent: #818cf8;
  --accent-strong: #a5b4fc;
  --accent-subtle: rgb(129 140 248 / .18);
  /* Indigo dark: a mid tone track carries the light thumb, so on and off never read alike. */
  --control-on: #818cf8;
  --control-glyph: #0b1120;
  --control-track: #23324b;
  --control-track-hover: #2c3d5a;
  --control-thumb: #e2e8f0;
  --control-thumb-on: #0b1120;
  --control-fill: #818cf8;
  --control-thumb-shadow: 0 0 0 .5px rgb(0 0 0 / .3), 0 1px 2px rgb(0 0 0 / .35), 0 2px 6px rgb(0 0 0 / .2);
  --success: #4ade80;
  --warning: #fbbf24;
  --danger: #f87171;
  --shadow-resting: 0 1px 2px rgb(0 0 0 / .18);
  --shadow-raised: 0 8px 22px rgb(0 0 0 / .22);
  --shadow-floating: 0 22px 55px rgb(0 0 0 / .34);
  --still-gradient-from: #312e81;
  --still-gradient-to: #4c1d95;
  --still-gradient-foreground: #e0e7ff;
  --still-gradient-soft: linear-gradient(135deg, #111a33, #141433);
  --still-gradient-line: linear-gradient(100deg, #4338ca, #6d28d9);
  --still-gradient-ink: linear-gradient(100deg, #c7d2fe, #ddd6fe);
}

:root[data-accent="neutral"] { --accent: #334155; --accent-strong: #1e293b; --accent-subtle: rgb(51 65 85 / .1); }
:root[data-accent="violet"] { --accent: #7747ff; --accent-strong: #5528ce; --accent-subtle: rgb(119 71 255 / .13); }
:root[data-accent="blue"] { --accent: #0562ef; --accent-strong: #074db7; --accent-subtle: rgb(5 98 239 / .12); }
:root[data-accent="green"] { --accent: #0db879; --accent-strong: #087c54; --accent-subtle: rgb(13 184 121 / .13); --accent-foreground: #102016; }
:root[data-accent="amber"] { --accent: #f3ad20; --accent-strong: #9c6300; --accent-subtle: rgb(243 173 32 / .16); --accent-foreground: #20190d; }
:root[data-accent="orange"] { --accent: #f48120; --accent-strong: #aa4700; --accent-subtle: rgb(244 129 32 / .13); --accent-foreground: #17130f; }
:root[data-accent="coral"] { --accent: #f15f55; --accent-strong: #b92c27; --accent-subtle: rgb(241 95 85 / .14); --accent-foreground: #21110f; }
:root[data-accent="rose"] { --accent: #ed4e9d; --accent-strong: #ae2570; --accent-subtle: rgb(237 78 157 / .14); --accent-foreground: #250f1b; }
:root[data-theme="dark"][data-accent="neutral"] { --accent: #cbd5e1; --accent-strong: #e2e8f0; --accent-subtle: rgb(203 213 225 / .13); }
:root[data-theme="dark"][data-accent="violet"] { --accent: #a78bff; --accent-strong: #c7b7ff; --accent-subtle: rgb(119 71 255 / .22); }
:root[data-theme="dark"][data-accent="blue"] { --accent: #6ba3ff; --accent-strong: #a4c7ff; --accent-subtle: rgb(5 98 239 / .22); }
:root[data-theme="dark"][data-accent="green"] { --accent: #53dca6; --accent-strong: #93efd0; --accent-subtle: rgb(13 184 121 / .2); }
:root[data-theme="dark"][data-accent="amber"] { --accent: #ffcb62; --accent-strong: #ffe0a1; --accent-subtle: rgb(243 173 32 / .2); }
:root[data-theme="dark"][data-accent="orange"] { --accent: #ffad5e; --accent-strong: #ffd0a0; --accent-subtle: rgb(244 129 32 / .2); --accent-foreground: #17130f; }
:root[data-theme="dark"][data-accent="coral"] { --accent: #ff9386; --accent-strong: #ffc1ba; --accent-subtle: rgb(241 95 85 / .2); }
:root[data-theme="dark"][data-accent="rose"] { --accent: #ff8bc5; --accent-strong: #ffc0df; --accent-subtle: rgb(237 78 157 / .2); }

/* Selection control fills per accent. Light: the accent, deepened slightly where a white thumb needs it. Dark: a mid tone instead of the pastel
   text accent, so white thumbs and checks keep contrast without a neon track. Amber keeps a dark glyph because white on yellow washes out. */
:root[data-accent="neutral"] { --control-on: #334155; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="violet"] { --control-on: #7747ff; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="blue"] { --control-on: #0562ef; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="green"] { --control-on: #10a870; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="amber"] { --control-on: #eda11a; --control-thumb-on: #fff; --control-glyph: #2a1c03; }
:root[data-accent="orange"] { --control-on: #f07818; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="coral"] { --control-on: #ec564b; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="rose"] { --control-on: #e64494; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-theme="dark"][data-accent="neutral"] { --control-on: #cbd5e1; --control-thumb-on: #0b1120; --control-glyph: #0b1120; }
:root[data-theme="dark"][data-accent="violet"] { --control-on: #8a66ff; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #8a66ff; }
:root[data-theme="dark"][data-accent="blue"] { --control-on: #3b82f6; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #3b82f6; }
:root[data-theme="dark"][data-accent="green"] { --control-on: #1fae78; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #1fae78; }
:root[data-theme="dark"][data-accent="amber"] { --control-on: #e8a52a; --control-thumb-on: #fff; --control-glyph: #241803; --control-fill: #e8a52a; }
:root[data-theme="dark"][data-accent="orange"] { --control-on: #ef873a; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #ef873a; }
:root[data-theme="dark"][data-accent="coral"] { --control-on: #ec6a60; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #ec6a60; }
:root[data-theme="dark"][data-accent="rose"] { --control-on: #e457a0; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #e457a0; }

/* Chart series palette, shared by every chart. Series 1 is the accent itself; series 2 to 4 rotate its hue at lightness steps
   around it, so they stay distinct for every accent. A neutral accent falls back to a blue. Validated with the dataviz script
   across all eight accents in both themes: every pair (not only neighbours) clears CVD ΔE 9 and normal vision ΔE 17. Browsers
   without relative color get the neutral set. Override --series-1 to --series-4 on any element to rebrand a chart. */
:root { --series-1: #4f46e5; --series-2: #7128a5; --series-3: #e58f00; --series-4: #009e84; }
:root[data-theme="dark"] { --series-1: #818cf8; --series-2: #9c37be; --series-3: #e66e00; --series-4: #00a861; }
@supports (color: oklch(from red clamp(.4, l * sign(max(c - .02, 0)) + .5, .8) c h)) {
  :root {
    --series-1: oklch(from var(--accent) calc(l * sign(max(c - .02, 0)) + .58 * (1 - sign(max(c - .02, 0)))) calc(c * sign(max(c - .02, 0)) + .15 * (1 - sign(max(c - .02, 0)))) calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0)))));
    --series-2: oklch(from var(--accent) clamp(.45, l * sign(max(c - .02, 0)) + .58 * (1 - sign(max(c - .02, 0))) - 0.25, .76) .19 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 57));
    --series-3: oklch(from var(--accent) clamp(.45, l * sign(max(c - .02, 0)) + .58 * (1 - sign(max(c - .02, 0))) + 0.14, .76) .18 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 184));
    --series-4: oklch(from var(--accent) clamp(.45, l * sign(max(c - .02, 0)) + .58 * (1 - sign(max(c - .02, 0))), .76) .21 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 292));
  }
  :root[data-theme="dark"] {
    --series-1: oklch(from var(--accent) calc(l * sign(max(c - .02, 0)) + .73 * (1 - sign(max(c - .02, 0)))) calc(c * sign(max(c - .02, 0)) + .15 * (1 - sign(max(c - .02, 0)))) calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0)))));
    --series-2: oklch(from var(--accent) clamp(.485, l * sign(max(c - .02, 0)) + .73 * (1 - sign(max(c - .02, 0))) - 0.19, .665) .21 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 66));
    --series-3: oklch(from var(--accent) clamp(.485, l * sign(max(c - .02, 0)) + .73 * (1 - sign(max(c - .02, 0))) + 0.02, .665) .21 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 175));
    --series-4: oklch(from var(--accent) clamp(.485, l * sign(max(c - .02, 0)) + .73 * (1 - sign(max(c - .02, 0))) - 0.1, .665) .18 calc(h * sign(max(c - .02, 0)) + 250 * (1 - sign(max(c - .02, 0))) + 270));
  }
}

/* Focus. Pointer focus never draws a ring (product decision). Keyboard focus (:focus-visible) draws a subtle accent outline, so keyboard users
   can always see where they are (WCAG 2.4.7). Left out of the outline: text fields, which match :focus-visible on a mouse click too and show
   focus with their border and caret; menu items and listbox options, whose highlight fill marks the keyboard position; and tabindex="-1"
   targets (dialog panels, regions) that only receive focus from script.
   Tune it on :root or any element, no !important needed:
     --focus-outline           color (default: the accent, softened); set transparent to hide it
     --focus-outline-width     default 2px
     --focus-outline-offset    default 2px; components inside clipped containers set a negative offset */
:focus:not(:focus-visible),
:is(input:not([type="button"], [type="checkbox"], [type="color"], [type="file"], [type="image"], [type="radio"], [type="range"], [type="reset"], [type="submit"]), textarea, [contenteditable]:not([contenteditable="false"]), [role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], [tabindex="-1"]):focus { outline: none !important; }
:focus-visible:not(input:not([type="button"], [type="checkbox"], [type="color"], [type="file"], [type="image"], [type="radio"], [type="range"], [type="reset"], [type="submit"]), textarea, [contenteditable]:not([contenteditable="false"]), [role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], [tabindex="-1"]) {
  outline: var(--focus-outline-width, 2px) solid var(--focus-outline, color-mix(in oklab, var(--accent-strong) 72%, transparent)) !important;
  outline-offset: var(--focus-outline-offset, 2px) !important;
}
